import sys
from collections import deque

def main():
    n = int(sys.stdin.readline())
    p_list = []
    for _ in range(n):
        p = int(sys.stdin.readline())
        p_list.append(p)

    # Build adjacency list for the hierarchy
    adj = [[] for _ in range(n+1)]
    in_degree = [0] * (n+1)
    for i in range(1, n+1):
        p = p_list[i-1]
        if p != -1:
            adj[p].append(i)
            in_degree[i] += 1

    # Topological sort using Kahn's algorithm
    q = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            q.append(i)

    topo_order = []
    while q:
        u = q.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Assign colors (groups) using greedy approach
    color = [0] * (n+1)
    max_color = 0
    for u in topo_order:
        # Find the maximum color among all superiors
        max_superior_color = 0
        v = p_list[u-1]
        while v != -1:
            if color[v] > max_superior_color:
                max_superior_color = color[v]
            v = p_list[v-1]
        color[u] = max_superior_color + 1
        if color[u] > max_color:
            max_color = color[u]

    print(max_color)

if __name__ == "__main__":
    main()
